import { lookupOrder } from './order.service';

export function refundOrder(orderId: string): void {
  const order = lookupOrder(orderId);

  if (!order) {
    throw new Error(`Cannot refund: order ${orderId} does not exist`);
  }

  if (order.refunded) {
    throw new Error(`Cannot refund: order ${orderId} has already been refunded`);
  }

  if (order.total < 10) {
    throw new Error(`Cannot refund: order ${orderId} total of ${order.total} is below minimum refundable amount of 10`);
  }

  order.refunded = true;
}

